mapper.insert:
/* setFile */
INSERT INTO TM_FILEXM (
            ORIG_NAME
          , STOR_NAME
          , FILE_PATH
          , FILE_SIZE
          , MIME_TYPE
          , REGI_USER
          , REGI_DATE
) VALUES (  #{origName}
          , #{storName}
          , #{filePath}
          , #{fileSize}
          , #{mimeType}
          , #{regiUser,jdbcType=NUMERIC}
          , CURRENT_TIMESTAMP
)

mapper.delete:
DELETE /* delFileIfUnreferenced */
  FROM TM_FILEXM
 WHERE FILE_NUMB = #{fileNumb}
   AND NOT EXISTS (
           SELECT 1
             FROM TM_USERXM U
            WHERE U.PROF_NUMB = #{fileNumb}
               OR U.BGIM_NUMB = #{fileNumb}
       )
